#define TEST(name,expr) do { if(expr){testsPassed++;std::cout<<"  PASS: "<<name<<"\n";}else{testsFailed++;std::cout<<"  FAIL: "<<name<<" ("<<__FILE__<<":"<<__LINE__<<")\n";} } while(0)

static ProductionCombatShip MakeCombatShip(){ProductionCombatShip s;s.shipId="cadet-cutter";s.capacity.power=500;s.capacity.heat=500;s.capacity.mass=5000;s.capacity.droneBandwidth=8;s.capacity.hardpoints[(int)FittingHardpointSize::Small]=8;s.capacity.hardpoints[(int)FittingHardpointSize::Medium]=4;s.capacity.hardpoints[(int)FittingHardpointSize::Large]=2;s.capacity.hardpoints[(int)FittingHardpointSize::Utility]=8;s.availablePower=500;return s;}

static void TestPass266CombatFittingUnification(){std::cout<<"[Pass266CombatFittingUnification]\n";FittingSystem fitting;AdvancedCombatSystem combat;ShipFailureSystem failures;DroneOperationsSystem drones(8);CombatShipIntegration integration;auto ship=MakeCombatShip();TEST("Pass266 fitted weapon installs through one authority",integration.Install(ship,"autocannon_s","gun1",fitting,combat,failures,drones));TEST("Pass266 install creates physical subsystem",failures.Get("fit:gun1")!=nullptr);TEST("Pass266 installed weapon creates combat runtime",combat.Get("weapon:gun1")!=nullptr);auto shot=integration.Fire(ship,"gun1",combat,failures);TEST("Pass266 fitted weapon is the firing authority",shot.fired&&shot.damage>0&&ship.availablePower<500);}
static void TestPass267PhysicalDamage(){std::cout<<"[Pass267PhysicalDamage]\n";FittingSystem fitting;AdvancedCombatSystem combat;ShipFailureSystem failures;DroneOperationsSystem drones(8);CombatShipIntegration integration;auto ship=MakeCombatShip();integration.Install(ship,"autocannon_s","gun1",fitting,combat,failures,drones);TEST("Pass267 module damage targets installed subsystem",integration.ApplyModuleDamage(ship,"gun1",200,failures));TEST("Pass267 destroyed visible module becomes disabled",failures.Get("fit:gun1")->state==FailureState::Destroyed);auto shot=integration.Fire(ship,"gun1",combat,failures);TEST("Pass267 destroyed weapon cannot fire",!shot.fired&&shot.reason=="weapon subsystem disabled");TEST("Pass267 unrelated equipment ID cannot be damaged",!integration.ApplyModuleDamage(ship,"missing",10,failures));}
static void TestPass268RepairMaintenance(){std::cout<<"[Pass268RepairMaintenance]\n";FittingSystem fitting;AdvancedCombatSystem combat;ShipFailureSystem failures;DroneOperationsSystem drones(8);CombatShipIntegration integration;EngineeringRepairSystem repairs;repairs.SetResources({100,10,1});auto ship=MakeCombatShip();integration.Install(ship,"autocannon_s","gun1",fitting,combat,failures,drones);integration.ApplyModuleDamage(ship,"gun1",40,failures);double before=failures.Get("fit:gun1")->integrity;TEST("Pass268 repair job binds actual installed module",integration.BeginRepair(ship,"gun1",failures,repairs,20));double restored=integration.AdvanceRepair(ship,"gun1",1,repairs,failures);TEST("Pass268 repair work restores failure authority",restored>0&&failures.Get("fit:gun1")->integrity>before);TEST("Pass268 repair consumes physical spare parts",repairs.Resources().spareParts<100);}
static void TestPass269DroneFitting(){std::cout<<"[Pass269DroneFitting]\n";FittingSystem fitting;AdvancedCombatSystem combat;ShipFailureSystem failures;DroneOperationsSystem drones(8);CombatShipIntegration integration;auto ship=MakeCombatShip();TEST("Pass269 fitted mining-drone bay installs",integration.Install(ship,"mining_drone","bay1",fitting,combat,failures,drones));TEST("Pass269 fitted bay creates physical drone asset",drones.Get("drone:bay1")!=nullptr);TEST("Pass269 fitted drone physically launches",drones.Launch("drone:bay1"));TEST("Pass269 deployed mining drone accepts asteroid job",drones.Assign("drone:bay1","asteroid-22"));drones.Tick(2);TEST("Pass269 mining drone accumulates physical cargo",drones.Get("drone:bay1")->cargo>0);}
static void TestPass270SensorsEwar(){std::cout<<"[Pass270SensorsEwar]\n";FittingSystem fitting;AdvancedCombatSystem combat;ShipFailureSystem failures;DroneOperationsSystem drones(8);CombatShipIntegration integration;ElectronicWarfareSystem ewar;auto ship=MakeCombatShip();integration.Install(ship,"survey_scanner","sensor1",fitting,combat,failures,drones);EnvironmentalExposureReport env;env.sensorPenalty=.25;env.propulsionPenalty=.1;ewar.Apply({"jam",EWarEffectType::SensorJam,.5,10,"pirate"});auto report=integration.EvaluateSensors(ship,ewar,env,failures);TEST("Pass270 environmental and EWAR penalties share sensor authority",report.sensorMultiplier<.5);TEST("Pass270 sensor range is derived from resulting capability",report.range<ship.baseSensorRange);integration.ApplyModuleDamage(ship,"sensor1",30,failures);auto damaged=integration.EvaluateSensors(ship,ewar,env,failures);TEST("Pass270 physical sensor damage further reduces scan range",damaged.range<report.range);}

static GalaxySector MakeRichSector(){GalaxyGenerator g(44021);g.planetProbability=1.0f;g.eventStageProbability=0.0f;g.minPointsOfInterest=6;g.maxPointsOfInterest=6;return g.GenerateSector(2,3,0);}
static void TestPass271SystemMapProduction(){std::cout<<"[Pass271SystemMapProduction]\n";auto sector=MakeRichSector();SystemNavigationSystem nav;NavigationMiningIntegration integration;auto map=integration.BuildMapAndNavigation(sector,nav);TEST("Pass271 system map contains generated celestial/navigation content",!map.nodes.empty());TEST("Pass271 map registration populates shared navigation authority",nav.GetDiscovered().size()>=1);std::size_t known=0;for(auto&n:map.nodes)if(n.known)known++;TEST("Pass271 known map nodes remain intelligence-filtered",known>0);}
static void TestPass272VectorTravelProduction(){std::cout<<"[Pass272VectorTravelProduction]\n";auto sector=MakeRichSector();SystemNavigationSystem nav;NavigationMiningIntegration integration;auto map=integration.BuildMapAndNavigation(sector,nav);std::uint64_t id=0;for(auto&n:map.nodes)if(n.known&&n.warpable){id=n.id;break;}AstronomicalPosition from;auto plan=integration.PlanVector(nav,from,id,8e9,1e9);TEST("Pass272 vector plan resolves shared map destination",id!=0&&plan.valid);VectorTravelSystem travel;VectorTravelSession session;TEST("Pass272 vector travel begins from valid plan",travel.Begin(session,plan));for(int i=0;i<1000&&travel.InTransit(session);++i)travel.Update(session,5);TEST("Pass272 align-charge-cruise-decelerate reaches completion",session.stage==VectorTravelStage::Complete);}
static void TestPass273AstronomicalPresentationIII(){std::cout<<"[Pass273AstronomicalPresentationIII]\n";auto sector=MakeRichSector();NavigationMiningIntegration integration;auto scene=integration.EvaluateLocalCelestials(sector,{0,0,0});TEST("Pass273 local flight renders at most one major celestial disc",scene.majorDiscs.size()<=1);if(!sector.planets.empty()){CelestialEnvironmentSystem celestial;auto profile=celestial.ProfileFor(sector.planets.front());TEST("Pass273 planet presentation remains at least 2.8x baseline",profile.radiusMultiplier>=2.8f);TEST("Pass273 giant local celestial may exceed viewport width",profile.maximumScreenFraction>=1.5f);}else TEST("Pass273 generated acceptance sector contains planets",false);}
static void TestPass274MassiveMiningRegions(){std::cout<<"[Pass274MassiveMiningRegions]\n";BeltMacroRegion belt;belt.id="outer-belt";belt.seed=8877;belt.conceptualCellCount=1500000;belt.conceptualLengthMeters=4e12;belt.localAsteroidBudget=24;RegionStreamingSystem streaming;NavigationMiningIntegration integration;auto state=integration.EnterBelt(belt,{10,20},streaming);TEST("Pass274 huge belt materializes only local asteroid budget",!state.materialized.asteroids.empty()&&state.materialized.asteroids.size()<=24);TEST("Pass274 entered belt cell is permanently surveyed",streaming.IsSurveyed("outer-belt",{10,20}));auto node=state.materialized.asteroids.front().id;TEST("Pass274 local asteroid depletion is persistent",integration.MineNode(state,node,streaming)&&streaming.IsDepleted(node));auto next=integration.NextUnsurveyed(state,streaming,19);TEST("Pass274 player can warp to another unsurveyed belt region",!(next==state.cell));}
