static StationBuildPlan MakeStationPlan(bool services){StationBuildPlan p;p.name="Frontier Hub";p.placement.kind=StationLocationKind::DeepSpace;p.placement.hasPermission=true;StationBuilderSystem b;b.AddModule(p,{StationModuleType::Core,"core",100,0,0},{0,0});b.AddModule(p,{StationModuleType::Power,"power",80,100,0},{1,0});b.AddModule(p,{StationModuleType::Dock,"dock",60,-10,50},{2,0});if(services){b.AddModule(p,{StationModuleType::Market,"market",60,-8,20},{3,0});b.AddModule(p,{StationModuleType::Repair,"repair",60,-8,10},{4,0});b.AddModule(p,{StationModuleType::Shipyard,"yard",120,-30,100},{5,0});}return p;}
static std::unordered_map<std::string,double> HugeStationMaterials(){return{{"structural_alloy",1e6},{"industrial_electronics",1e6},{"reactor_components",1e6},{"precision_machinery",1e6},{"weapon_components",1e6}};}
static void TestPass278StationBuilderProductionII(){std::cout<<"[Pass278StationBuilderProductionII]\n";StationBuilderSystem builder;auto p=MakeStationPlan(false);auto v=builder.Validate(p);TEST("Pass278 free-space station modules form connected build",v.valid);InfrastructureIndustryIntegration integration;auto inv=HugeStationMaterials();auto result=integration.CommissionStation(p,builder,inv);TEST("Pass278 station construction consumes real material bill",result.commissioned&&result.structuralMaterialConsumed>0);TEST("Pass278 commissioned core/dock emerges as usable outpost",!result.roles.empty());}
static void TestPass279StationOperations(){std::cout<<"[Pass279StationOperations]\n";StationBuilderSystem builder;auto p=MakeStationPlan(true);InfrastructureIndustryIntegration integration;auto inv=HugeStationMaterials();auto result=integration.CommissionStation(p,builder,inv);TEST("Pass279 operational station commissions full service modules",result.commissioned);TEST("Pass279 shipyard module activates shipyard service",result.services.shipyard);TEST("Pass279 market and repair services share station module authority",result.services.market&&result.services.repairHull&&result.services.repairModules);}
